const thread = items[0].json; // assuming this is the only item

let formatted = '';

for (let i = 0; i < thread.Role.length; i++) {
  const role = thread.Role[i];
  const direction = thread.Direction[i];
  const message = thread.Message[i].trim();

  formatted += `[${role}] (${direction}): ${message}\n\n`;
}

return [{ json: { formattedThread: formatted.trim() } }];

