const inputData = items[0].json;
const starts = inputData.start;
const ends = inputData.end;

const merged = [];

function toNaturalLanguage(isoString) {
  const date = new Date(isoString);
  const options = {
    weekday: 'long',
    month: 'long',
    day: 'numeric',
    hour: 'numeric',
    minute: '2-digit',
    timeZoneName: 'short'
  };
  return date.toLocaleString('en-US', options);
}

for (let i = 0; i < starts.length; i++) {
  merged.push({
    start: starts[i],
    end: ends[i],
    naturalStart: toNaturalLanguage(starts[i]),
    naturalEnd: toNaturalLanguage(ends[i])
  });
}

return [
  {
    json: {
      readableSlots: JSON.stringify(merged)
    }
  }
];

